/**
 * Token-bucket rate limiter with a FIFO fairness queue.
 *
 * - `capacity`: max tokens the bucket can hold (burst size).
 * - `refillPerSec`: tokens added per second, continuously pro-rated
 *   (fractional accumulation via elapsed wall time, not fixed windows).
 *
 * Calls consume one token. When the bucket is empty, calls queue FIFO and are
 * granted as tokens refill. A queued call can give up with `timeoutMs`,
 * rejecting with `TimeoutError`. `cancelAll()` rejects everything queued.
 */

export class TimeoutError extends Error {
  constructor(message = 'Rate limiter call timed out while waiting in queue') {
    super(message);
    this.name = 'TimeoutError';
  }
}

export class CancelledError extends Error {
  constructor(message = 'Call was cancelled while waiting in queue') {
    super(message);
    this.name = 'CancelledError';
  }
}

export interface CreateLimiterOptions {
  /** Maximum number of tokens the bucket can hold (also the burst size). */
  capacity: number;
  /** Tokens replenished per second, applied continuously. */
  refillPerSec: number;
}

export interface CallOptions {
  /**
   * Max time (ms) this call may spend waiting in the queue before being
   * rejected with a TimeoutError. Only applies to queue wait time; it does
   * not limit the wrapped function's execution.
   */
  timeoutMs?: number;
}

export interface LimiterStats {
  /** Whole tokens currently in the bucket (fractional remainder excluded). */
  available: number;
  /** Number of calls currently waiting in the FIFO queue. */
  queued: number;
}

export interface Limiter {
  /** Run an async fn through the limiter: consumes one token per call. */
  <T>(fn: () => T | Promise<T>, options?: CallOptions): Promise<T>;
  run<T>(fn: () => T | Promise<T>, options?: CallOptions): Promise<T>;
  /** Wrap any async function into a rate-limited one. */
  wrap<F extends (...args: any[]) => any>(
    fn: F,
    options?: CallOptions
  ): (...args: Parameters<F>) => ReturnType<F> extends never ? never : Promise<Awaited<ReturnType<F>>>;
  stats(): LimiterStats;
  /** Reject every queued call with CancelledError and drain the queue. */
  cancelAll(): void;
}

interface Waiter {
  resolve: () => void;
  reject: (err: unknown) => void;
  timeoutTimer?: ReturnType<typeof setTimeout>;
}

/** Tolerance for floating-point drift in continuous refill math. */
const EPSILON = 1e-9;

export function createLimiter({ capacity, refillPerSec }: CreateLimiterOptions): Limiter {
  if (!Number.isFinite(capacity) || capacity < 1) {
    throw new Error('capacity must be a finite number >= 1');
  }
  if (!Number.isFinite(refillPerSec) || refillPerSec <= 0) {
    throw new Error('refillPerSec must be a finite number > 0');
  }

  let tokens = capacity;
  let lastRefillAt = Date.now();
  let queue: Waiter[] = [];
  let grantTimer: ReturnType<typeof setTimeout> | null = null;

  const now = () => Date.now();

  /** Add tokens for elapsed time since the last refill (continuous math). */
  const refill = (): void => {
    const t = now();
    const elapsedMs = t - lastRefillAt;
    if (elapsedMs <= 0) return;
    tokens = Math.min(capacity, tokens + (elapsedMs / 1000) * refillPerSec);
    lastRefillAt = t;
  };

  const clearGrantTimer = (): void => {
    if (grantTimer !== null) {
      clearTimeout(grantTimer);
      grantTimer = null;
    }
  };

  /**
   * Grant tokens to queued callers in FIFO order while at least one whole
   * token is available, then schedule the timer for the next grantable token.
   */
  const grant = (): void => {
    refill();
    while (queue.length > 0 && tokens >= 1 - EPSILON) {
      tokens -= 1;
      const waiter = queue.shift()!;
      if (waiter.timeoutTimer) clearTimeout(waiter.timeoutTimer);
      waiter.resolve();
    }
    scheduleNextGrant();
  };

  const scheduleNextGrant = (): void => {
    clearGrantTimer();
    if (queue.length === 0) return;
    refill();
    if (tokens >= 1 - EPSILON) {
      grant();
      return;
    }
    const waitMs = ((1 - tokens) * 1000) / refillPerSec;
    grantTimer = setTimeout(() => {
      grantTimer = null;
      grant();
    }, Math.max(waitMs, 0));
  };

  const acquire = ({ timeoutMs }: CallOptions = {}): Promise<void> =>
    new Promise<void>((resolve, reject) => {
      refill();
      // Fast path: a full token is available and nobody is waiting ahead of
      // us (FIFO fairness means we must never jump the queue).
      if (tokens >= 1 - EPSILON && queue.length === 0) {
        tokens -= 1;
        resolve();
        return;
      }

      const waiter: Waiter = { resolve, reject };
      if (timeoutMs !== undefined) {
        waiter.timeoutTimer = setTimeout(() => {
          const idx = queue.indexOf(waiter);
          if (idx !== -1) queue.splice(idx, 1);
          // Re-derive timing for the new head of the queue; note that a
          // timed-out call consumed no token, so the budget is untouched.
          scheduleNextGrant();
          reject(new TimeoutError(`Timed out after ${timeoutMs}ms waiting for a token`));
        }, timeoutMs);
      }
      queue.push(waiter);
      if (queue.length === 1) scheduleNextGrant();
    });

  const run = async <T>(fn: () => T | Promise<T>, options?: CallOptions): Promise<T> => {
    await acquire(options);
    return await fn();
  };

  const wrap = <F extends (...args: any[]) => any>(
    fn: F,
    options?: CallOptions
  ): ((...args: Parameters<F>) => Promise<Awaited<ReturnType<F>>>) => {
    return async (...args: Parameters<F>): Promise<Awaited<ReturnType<F>>> =>
      run(() => fn(...args), options);
  };

  const cancelAll = (): void => {
    clearGrantTimer();
    const waiting = queue;
    queue = [];
    for (const waiter of waiting) {
      if (waiter.timeoutTimer) clearTimeout(waiter.timeoutTimer);
      waiter.reject(new CancelledError());
    }
  };

  const stats = (): LimiterStats => {
    refill();
    return {
      available: Math.floor(tokens + EPSILON),
      queued: queue.length,
    };
  };

  const limiter = ((fn: () => unknown, options?: CallOptions) =>
    run(fn as () => unknown, options)) as Limiter;

  limiter.run = run;
  limiter.wrap = wrap as Limiter['wrap'];
  limiter.stats = stats;
  limiter.cancelAll = cancelAll;

  return limiter;
}

