    new Promise<void>((resolve, reject) => {
      refill();
      // Fast path: a full token is available and nobody is waiting ahead of
      // us (FIFO fairness means we must never jump the queue).
      if (tokens >= 1 - EPSILON && queue.length === 0) {
        tokens -= 1;
        resolve();
        return;
      }

      const waiter: Waiter = { resolve, reject };
      if (timeoutMs !== undefined) {
        waiter.timeoutTimer = setTimeout(() => {
          const idx = queue.indexOf(waiter);
          if (idx !== -1) queue.splice(idx, 1);
          // Re-derive timing for the new head of the queue; note that a
          // timed-out call consumed no token, so the budget is untouched.
          scheduleNextGrant();
          reject(new TimeoutError(`Timed out after ${timeoutMs}ms waiting for a token`));
        }, timeoutMs);
      }
      queue.push(waiter);
      if (queue.length === 1) scheduleNextGrant();
    });

