import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { CancelledError, TimeoutError, createLimiter } from '../src/limiter.js';

beforeEach(() => {
  vi.useFakeTimers();
});

afterEach(() => {
  vi.useRealTimers();
});

/** Attach a catch handler immediately so rejections are never unhandled. */
function silence<T>(p: Promise<T>): Promise<T> {
  p.catch(() => {});
  return p;
}

describe('createLimiter', () => {
  it('runs a burst of up to capacity calls immediately', async () => {
    const limiter = createLimiter({ capacity: 3, refillPerSec: 3 });
    const order: number[] = [];

    const promises = [1, 2, 3].map((i) =>
      limiter(async () => {
        order.push(i);
        return i;
      })
    );

    // No timer advance needed: the whole burst fits in the bucket.
    await vi.advanceTimersByTimeAsync(0);

    expect(order).toEqual([1, 2, 3]);
    expect(await Promise.all(promises)).toEqual([1, 2, 3]);
    expect(limiter.stats()).toEqual({ available: 0, queued: 0 });
  });

  it('makes the next call wait exactly the refill interval (continuous refill)', async () => {
    // 1 token per 500ms.
    const limiter = createLimiter({ capacity: 2, refillPerSec: 2 });
    const finishedAt: Record<string, number> = {};

    const first = [1, 2].map((i) => limiter(async () => void (finishedAt[`a${i}`] = Date.now())));
    const third = silence(
      limiter(async () => void (finishedAt.b = Date.now()))
    );

    await vi.advanceTimersByTimeAsync(0);
    expect(finishedAt.a1).toBe(0);
    expect(finishedAt.a2).toBe(0);
    expect(limiter.stats()).toEqual({ available: 0, queued: 1 });

    // Just before one full token has accrued: still queued.
    await vi.advanceTimersByTimeAsync(499);
    expect(finishedAt.b).toBeUndefined();

    // Exactly at the refill interval the queued call resolves.
    await vi.advanceTimersByTimeAsync(1);
    expect(finishedAt.b).toBe(500);
    await expect(third).resolves.toBeUndefined();
    expect(limiter.stats().queued).toBe(0);
  });

  it('grants queued calls in FIFO order as tokens refill', async () => {
    // One token every 100ms.
    const limiter = createLimiter({ capacity: 1, refillPerSec: 10 });
    const results: number[] = [];
    const times: number[] = [];

    const jobs = [1, 2, 3, 4, 5].map((i) =>
      silence(
        limiter(async () => {
          results.push(i);
          times.push(Date.now());
          return i;
        })
      )
    );

    await vi.advanceTimersByTimeAsync(0);
    // Job 1 ran immediately; jobs 2..5 are queued behind it in order.
    expect(results).toEqual([1]);
    expect(limiter.stats()).toEqual({ available: 0, queued: 4 });

    for (let i = 1; i <= 4; i++) {
      await vi.advanceTimersByTimeAsync(100);
      expect(results.length).toBe(i + 1);
    }

    expect(results).toEqual([1, 2, 3, 4, 5]);
    expect(times).toEqual([100, 200, 300, 400]);
    expect(await Promise.all(jobs)).toEqual([2, 3, 4, 5]);
    expect(limiter.stats()).toEqual({ available: 0, queued: 0 });
  });

  it('rejects a queued call with TimeoutError at the right time and frees no token', async () => {
    // One token every 2000ms.
    const limiter = createLimiter({ capacity: 1, refillPerSec: 0.5 });
    let slowRan = false;
    let patientRan = false;

    await limiter(async () => void (slowRan = true));
    expect(slowRan).toBe(true);

    const impatient = silence(
      limiter(async () => void (patientRan = true), { timeoutMs: 500 })
    );
    const patient = limiter(async () => void (patientRan = true));

    await vi.advanceTimersByTimeAsync(0);
    expect(limiter.stats()).toEqual({ available: 0, queued: 2 });

    let timeoutErr: unknown;
    const caught = impatient.then(() => {}, (e) => (timeoutErr = e));

    await vi.advanceTimersByTimeAsync(500);
    await caught;

    expect(timeoutErr).toBeInstanceOf(TimeoutError);
    expect(patientRan).toBe(false);
    // The timed-out call consumed no token: budget still empty with exactly
    // one waiter left (the patient call), not zero.
    expect(limiter.stats()).toEqual({ available: 0, queued: 1 });

    // The patient call resolves on the original schedule — the timeout did
    // not free a token that would have let it run early.
    await vi.advanceTimersByTimeAsync(1500);
    expect(patientRan).toBe(true);
    expect(Date.now()).toBe(2000);
    await expect(patient).resolves.toBeUndefined();
    expect(limiter.stats().queued).toBe(0);
  });

  it('reports accurate stats mid-scenario including fractional refill', async () => {
    // Half a token per 250ms -> full token per 500ms.
    const limiter = createLimiter({ capacity: 3, refillPerSec: 2 });
    const done: number[] = [];

    for (const i of [1, 2, 3, 4, 5]) silence(limiter(async () => void done.push(i)));

    await vi.advanceTimersByTimeAsync(0);
    expect(done).toEqual([1, 2, 3]);
    expect(limiter.stats()).toEqual({ available: 0, queued: 2 });

    // After 250ms only half a token exists: nothing grantable yet.
    await vi.advanceTimersByTimeAsync(250);
    expect(limiter.stats()).toEqual({ available: 0, queued: 2 });

    // At t=500ms exactly one token has accrued: head of queue runs.
    await vi.advanceTimersByTimeAsync(250);
    expect(done).toEqual([1, 2, 3, 4]);
    expect(limiter.stats()).toEqual({ available: 0, queued: 1 });

    // Bucket never exceeds capacity even while idle.
    await vi.advanceTimersByTimeAsync(10_000);
    expect(limiter.stats()).toEqual({ available: 3, queued: 0 });
    expect(done).toEqual([1, 2, 3, 4, 5]);
  });

  it('cancelAll rejects everything queued and the limiter keeps working after', async () => {
    const limiter = createLimiter({ capacity: 1, refillPerSec: 10 });

    let firstRan = false;
    await limiter(async () => void (firstRan = true));
    expect(firstRan).toBe(true);

    const errors: unknown[] = [];
    const queued = [1, 2, 3].map(() =>
      limiter(async () => 'never').catch((e) => errors.push(e))
    );

    await vi.advanceTimersByTimeAsync(0);
    expect(limiter.stats()).toEqual({ available: 0, queued: 3 });

    limiter.cancelAll();
    await Promise.all(queued);

    expect(errors).toHaveLength(3);
    for (const e of errors) expect(e).toBeInstanceOf(CancelledError);
    expect(limiter.stats()).toEqual({ available: 0, queued: 0 });

    // Refilled bucket serves new work fine after cancellation.
    await vi.advanceTimersByTimeAsync(100);
    expect(await limiter(async () => 'ok')).toBe('ok');
    expect(limiter.stats().available).toBe(0);
  });

  it('supports wrap() for rate-limiting any async function', async () => {
    const limiter = createLimiter({ capacity: 1, refillPerSec: 5 }); // 200ms/token
    const limitedFetch = limiter.wrap(async (url: string) => `body:${url}`);

    const first = limitedFetch('a');
    const second = silence(limitedFetch('b'));

    await vi.advanceTimersByTimeAsync(0);
    await expect(first).resolves.toBe('body:a');

    await vi.advanceTimersByTimeAsync(199);
    await expect(second).resolves.toBeUndefined(); // not yet
    expect(second).toBeDefined();

    await vi.advanceTimersByTimeAsync(1);
    await expect(second).resolves.toBe('body:b');
  });

  it('propagates wrapped function failures without leaking the token bookkeeping', async () => {
    const limiter = createLimiter({ capacity: 1, refillPerSec: 100 });
    await expect(
      limiter(async () => {
        throw new Error('boom');
      })
    ).rejects.toThrow('boom');

    // Token was consumed by the failed call; next call must queue normally.
    const next = limiter(async () => 'recovered');
    await vi.advanceTimersByTimeAsync(10); // 100/s -> plenty of tokens by now
    await expect(next).resolves.toBe('recovered');
  });
});

